<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class handler extends lib { var $mark = "<!-- THIS CONTENT IS STATIC CACHE -->\n"; var $options; var $log_id = 'static-cache'; var $abspath; public function init() { } public function is_excluded($url) { if ($this->options->qc_static_cache_exclude_path) foreach ($this->options->qc_static_cache_exclude_path as $path) { if (strstr($url, $path) !== false) return true; } return false; } public function get_path($url, $abspath, $make_dir = true) { $path = urldecode(dirname($url)); $filename = urldecode(basename($url)); if (!preg_match('/\.html?$/i', $filename)) { $path .= $path == DIRECTORY_SEPARATOR ? $filename . DIRECTORY_SEPARATOR : DIRECTORY_SEPARATOR . $filename . DIRECTORY_SEPARATOR; $filename = 'index.html'; } elseif ($path != DIRECTORY_SEPARATOR) { $path .= DIRECTORY_SEPARATOR; } if ($make_dir) $this->create_dir($path, $abspath); return $abspath . $path . $filename; } public function create_dir($path, $abspath) { $pathArr = array_values(array_filter(preg_split('/[\\\|\/]/', $path))); if (!is_dir($abspath . $path)) $this->make_dir($pathArr, $abspath); } public function make_dir($pathArr, $path='', $level = 0) { $path .= DIRECTORY_SEPARATOR . $pathArr[$level] . DIRECTORY_SEPARATOR; if (!is_dir($path) || !file_exists($path)) { mkdir($path); } $level++; if ($level < count($pathArr)) $this->make_dir($pathArr, $path, $level); } public function set_pure_cache($path, $args) { $args = apply_filters( 'qqworld-collector-static-cache-fix-url-args', $args); sleep($this->options->qc_static_cache_stress); $response = wp_remote_get( home_url($args), array( 'sslverify' => false, 'headers' => array( 'Connection' => 'Close' ) ) ); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) { $content = wp_remote_retrieve_body($response); $content = apply_filters( 'qqworld-collector-static-cache-content', $content ); $content = $this->mark . $content; try { $content = $this->minify_html($content); $result = file_put_contents($path, $content); if (!$result) do_action( 'qqworld-collector-log', $this->log_id, 'Can not write content (Pure Cache), Path:', $path ); } catch (Throwable $t) { do_action( 'qqworld-collector-log', $this->log_id, 'Can not write content (Pure Cache), Message:', $t->getMessage() ); } catch (Exception $e) { do_action( 'qqworld-collector-log', $this->log_id, 'Can not write content (Pure Cache), Message:', $e->getMessage() ); } return $result; } else { do_action( 'qqworld-collector-log', $this->log_id, 'Can not get cache content (Pure Cache), url:', print_r(home_url($args), true) . "\n" . print_r($response, true) ); } return false; } public function set_half_cache($path, $url) { sleep($this->options->qc_static_cache_stress); if (file_exists($path)) unlink($path); $response = wp_remote_get( $url, array( 'sslverify' => false, 'headers' => array( 'Connection' => 'Close' ) ) ); $response_code = wp_remote_retrieve_response_code($response); if ($response_code == 200) { $content = wp_remote_retrieve_body($response); $content = apply_filters( 'qqworld-collector-static-cache-content', $content ); $content = $this->mark . $content; try { $content = $this->minify_html($content); $result = file_put_contents($path, $content); if (!$result) do_action( 'qqworld-collector-log', $this->log_id, 'Can not write content (Pure Cache), Path:', $path ); } catch (Throwable $t) { do_action( 'qqworld-collector-log', $this->log_id, 'Can not write content (Pure Cache), Message:', $t->getMessage() ); } catch (Exception $e) { do_action( 'qqworld-collector-log', $this->log_id, 'Can not write content (Pure Cache), Message:', $e->getMessage() ); } return $result; } else { do_action( 'qqworld-collector-log', $this->log_id, 'Can not get cache content (Half Cache), url:', print_r($url, true) . "\n" . print_r($response, true) ); } return false; } } ?>